private bool UpdatePrinterErrorStatus()
{
    bool printerErrorStatusWasUpdated = false;
    List/ lstPrintError = new List/();                    // List of errors the printer is reporting

    PrinterInfo printerInfo = new PrinterInfo(m_printerName);

    string sJobQueue = printerInfo.GetErrorCodes();

    if (sJobQueue != null)
    {
        string[] arJobRecords = sJobQueue.Split(';');

        foreach (string sJobRecord in arJobRecords)
        {
            // Split into job number, user id and job status strings.
            string[] arFieldsWithinThisRecord = sJobRecord.Split(',');

            // Is this the last "ERR:" record?
            if (arFieldsWithinThisRecord.Count() > 5)
            {
                string sErrorNumber = arFieldsWithinThisRecord[0].Substring(4, arFieldsWithinThisRecord[0].Length - 4); // Remove "ERR:"

                // Don't include the last error number.
                if ((int.Parse(sErrorNumber) != 0) || (int.Parse(arFieldsWithinThisRecord[1]) != 0) || (int.Parse(arFieldsWithinThisRecord[2]) != 0) || (int.Parse(arFieldsWithinThisRecord[3]) != 0) || (int.Parse(arFieldsWithinThisRecord[4]) != 0) || (int.Parse(arFieldsWithinThisRecord[5]) != 0))
                {
                    lstPrintError.Add(new PrintError(int.Parse(arFieldsWithinThisRecord[3]), arFieldsWithinThisRecord[2], int.Parse(arFieldsWithinThisRecord[0]), int.Parse(arFieldsWithinThisRecord[1])));
                }
            }        
        }

        printerErrorStatusWasUpdated = true;
        m_deviceStatus.UpdateErrorAddedAndDeletedLists(new List/(lstPrintError.ToArray()));
    }

    return (printerErrorStatusWasUpdated);
}

	PrinterInfo printerInfo = new PrinterInfo(m_printerName);

    List(IJobStatusPublic) lstCurrentJobStatus = new List(IJobStatusPublic)();
    List(GlobalStatus) lstCurrentGlobalStatus = new List(GlobalStatus)();

    string sJobQueue = printerInfo.GetJobQueue();

    // Format of the job queue is as indicated in the GetJobQueue method documentation.

    string[] arJobRecords = sJobQueue.Split(';');

    foreach (string sJobRecord in arJobRecords)
    {
        // Split into job number, user id and job status strings.
        string[] arFieldsWithinThisRecord = sJobRecord.Split(',');

        // Is this the last "JOB:" record?
        if (arFieldsWithinThisRecord.Count() > 8)
        {
            m_deviceStatus.GlobalPrinterStatus = int.Parse(arFieldsWithinThisRecord[8]);
            lstCurrentGlobalStatus.Add(new GlobalStatus(m_deviceStatus.GlobalPrinterStatus));
        }
        else if (arFieldsWithinThisRecord.Count() == 8)
        {
            string sJobNumber = arFieldsWithinThisRecord[0].Substring(4, arFieldsWithinThisRecord[0].Length - 4); // Remove "JOB:"

            //                                    Job Printer Number                      Job Spooler Number                      User Id                      Document                               Job Status                    Module Id                    Mag Status                              Chip Status
            lstCurrentJobStatus.Add(new JobStatus(int.Parse(sJobNumber), int.Parse(arFieldsWithinThisRecord[1]), arFieldsWithinThisRecord[2], arFieldsWithinThisRecord[3], int.Parse(arFieldsWithinThisRecord[4]), arFieldsWithinThisRecord[5], int.Parse(arFieldsWithinThisRecord[6]), int.Parse(arFieldsWithinThisRecord[7])));
        }
    }

member.returns:
The information is returned as a string in the following format for the HDP6600 model:

JOB :(job number),(hostname),(job status);

JOB :(job number), (hostname), (job status);

: 

JOB:00,00,00,(global printer status);

where:

This for active, waiting, and the last 5 completed jobs

(job number) internally generated by firmware, this unique job identifier should be used by other commands to refer to the job

(hostname) the number the spooler (Host) assigned to the job and is passed down as part of the print job



(job status) and (global printer status) are the current print processing statuses according to the T:Fargo.PrinterSDK.PrinterInfo.HDP6600JobProcessingStatus enumeration for the HDP6600.

