// Command to get the Firmware Version from the DTC550 (Command 4, Instruction 4, Parameter 1=3)
byte[] cmdGetFWVersion = {
                             0x46, 0x67, 0x00, 0x00, 0x20, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x04, 0x00,
                             0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
                             0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x65, 0x50
                         };
PrinterInfo objPrinterInfo = new PrinterInfo(sPrinterName);

//Retrieve the data from the printer
byte[] bResponse = objPrinterInfo.Passthrough(cmdGetFWVersion);

ASCIIEncoding ASCII = new ASCIIEncoding();

//Convert the byte array back to a string
