    This code example allows for getting the DTC printer display content.

PrinterInfo printerInfo = new PrinterInfo(sPrinterName);

byte[] bytes = new byte[] { };
bytes = printerInfo.SendAPDU(5, 2, 0, 0, 0, null);

if (bytes != null)
{
    MemoryStream mStream = new MemoryStream(bytes);
    System.Drawing.Bitmap bitmap = (System.Drawing.Bitmap)System.Drawing.Bitmap.FromStream(mStream);
}

