PrintJob printJob = new PrintJob(pPrinterName);

// add image to print
if (!printJob.AddPrintImageElement((object)("example.bmp"), /*from_file*/1, /*x*/0, /*y*/0, /*front*/0))
{
    // emit error - adding print image element failed
    return;
}

// do printing
printJob.DoPrint("The Print Job Name");

// wait for the printer to finish all its jobs
printJob.FinishDoc();

PrintJob printJob = new PrintJob(pPrinterName);

// add the 1st track data
