 using System;
 using Fargo.PrinterSDK;


	public class SDKTest 
	{
		public static void Main() 
		{

				Security objSecurity = new Security("DTC5000 Card Printer");
				PrinterInfo objInfo = new PrinterInfo("DTC5000 Card Printer");
				string ribbonOEMPartNo = objInfo.RibbonOEMPartNumber;

				if (objSecurity.OEMSecurityEnabled)
				{
					Console.Writeline("[SecureMark enabled]");
				}
				else if (ribbonOEMPartNo != null & Int32.Parse(ribbonOEMPartNo) < 0)
				{
					Console.Writeline("[secure ribbon/SecureMark disabled]");
				}
		}
	}
